package com.arcus.alert;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity{
static final String PREF="arcus_native";static final int PICK_SOUND=77;LinearLayout root,list,historyList;Spinner marketSpinner,modeSpinner;TextView status,livePrice,soundName;EditText searchBox;final ArrayList<String> allNames=new ArrayList<>(),shownNames=new ArrayList<>();final Handler handler=new Handler(Looper.getMainLooper());
final Runnable refresh=new Runnable(){public void run(){refreshMarkets();handler.postDelayed(this,1000);}};
int bg=Color.rgb(10,16,29),card=Color.rgb(20,30,49),muted=Color.rgb(151,166,190),accent=Color.rgb(73,190,166);
public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);buildUi();startMonitor();handler.post(refresh);}
int dp(float v){return(int)(v*getResources().getDisplayMetrics().density);}GradientDrawable shape(int color,int radius,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
TextView text(String s,int z,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);return t;}TextView label(String s){TextView t=text(s,13,muted);t.setPadding(0,dp(12),0,dp(5));return t;}
LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}LinearLayout card(){LinearLayout l=column();l.setPadding(dp(15),dp(13),dp(15),dp(13));l.setBackground(shape(card,16,Color.rgb(38,54,78)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);root.addView(l,p);return l;}
EditText edit(String hint,int type){EditText e=new EditText(this);e.setSingleLine(true);e.setInputType(type);e.setHint(hint);e.setTextColor(Color.WHITE);e.setHintTextColor(muted);e.setPadding(dp(12),dp(7),dp(12),dp(7));e.setBackground(shape(Color.rgb(13,23,39),10,Color.rgb(54,75,102)));return e;}
Button button(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14);return b;}
void buildUi(){ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setBackgroundColor(bg);root=column();root.setPadding(dp(17),dp(22),dp(17),dp(28));sc.addView(root);setContentView(sc);
LinearLayout head=column();TextView title=text("🔔  Arcus Alert",28,Color.WHITE);title.setTypeface(null,Typeface.BOLD);head.addView(title);TextView sub=text("SMART PRICE MONITOR",11,accent);sub.setLetterSpacing(.12f);head.addView(sub);head.setPadding(0,0,0,dp(15));root.addView(head);
LinearLayout statusCard=card();status=text("●  Connecting to Arcus markets…",13,accent);statusCard.addView(status);
LinearLayout market=card();market.addView(label("SEARCH MARKET"));searchBox=edit("Type symbol · BTC, ETH…",1);market.addView(searchBox);market.addView(label("SELECT MARKET"));marketSpinner=new Spinner(this);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,shownNames));market.addView(marketSpinner);livePrice=text("Current price: waiting…",19,Color.WHITE);livePrice.setTypeface(null,Typeface.BOLD);livePrice.setPadding(0,dp(12),0,dp(2));market.addView(livePrice);
searchBox.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filterMarkets();}public void afterTextChanged(Editable e){}});marketSpinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){updatePrice();}});
LinearLayout addCard=card();TextView addTitle=text("Create price alert",20,Color.WHITE);addTitle.setTypeface(null,Typeface.BOLD);addCard.addView(addTitle);addCard.addView(label("TARGET PRICE"));EditText target=edit("e.g. 82980",8194);addCard.addView(target);addCard.addView(label("ALERT CONDITION"));modeSpinner=new Spinner(this);modeSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"At price · TradingView style","Touch / cross","Near · 0.1%"}));addCard.addView(modeSpinner);Button add=button("＋  Add alert");add.setTextColor(Color.WHITE);add.setBackground(shape(accent,12,0));LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(48));ap.topMargin=dp(14);addCard.addView(add,ap);add.setOnClickListener(v->addLevel(target));
LinearLayout sound=card();TextView st=text("Alert sound",18,Color.WHITE);st.setTypeface(null,Typeface.BOLD);sound.addView(st);soundName=text("Default notification sound",13,muted);soundName.setPadding(0,dp(5),0,dp(10));sound.addView(soundName);LinearLayout soundBtns=new LinearLayout(this);Button choose=button("Choose sound");Button test=button("▶ Test");soundBtns.addView(choose,new LinearLayout.LayoutParams(0,dp(44),1));soundBtns.addView(test,new LinearLayout.LayoutParams(0,dp(44),1));sound.addView(soundBtns);choose.setOnClickListener(v->pickSound());test.setOnClickListener(v->testSound());
TextView saved=text("Your alerts",21,Color.WHITE);saved.setTypeface(null,Typeface.BOLD);saved.setPadding(0,dp(8),0,dp(10));root.addView(saved);list=column();root.addView(list);
TextView hist=text("Notification history",19,Color.WHITE);hist.setTypeface(null,Typeface.BOLD);hist.setPadding(0,dp(14),0,dp(8));root.addView(hist);historyList=column();root.addView(historyList);Button clear=button("Clear history");root.addView(clear);clear.setOnClickListener(v->{getSharedPreferences(PREF,0).edit().putString("history","[]").apply();renderHistory();});
Button testNotif=button("Test notification");root.addView(testNotif);testNotif.setOnClickListener(v->sendTestNotification());TextView foot=text("Live prices refresh every second · Keep background activity unrestricted for reliable alerts.",12,muted);foot.setPadding(0,dp(16),0,0);root.addView(foot);renderLevels();renderHistory();updateSoundName();}
void startMonitor(){try{Intent i=new Intent(this,PriceMonitorService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception e){status.setText("Service error: "+e.getMessage());}}
JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}void save(JSONArray a){getSharedPreferences(PREF,0).edit().putString("levels",a.toString()).apply();}
String selected(){return marketSpinner==null||marketSpinner.getSelectedItem()==null?"":marketSpinner.getSelectedItem().toString();}
void filterMarkets(){String q=searchBox.getText().toString().trim().toLowerCase(Locale.ROOT),old=selected();shownNames.clear();for(String n:allNames)if(q.isEmpty()||n.toLowerCase(Locale.ROOT).contains(q))shownNames.add(n);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,shownNames));int p=shownNames.indexOf(old);if(p>=0)marketSpinner.setSelection(p);updatePrice();}
JSONObject find(JSONObject d,String symbol){if(symbol==null||symbol.isEmpty())return null;Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null&&(symbol.equalsIgnoreCase(key)||symbol.equalsIgnoreCase(o.optString("marketDisplayName"))||symbol.equalsIgnoreCase(o.optString("symbol"))||symbol.equalsIgnoreCase(o.optString("marketId"))))return o;}return null;}
void refreshMarkets(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty()){status.setText("●  Waiting for market data…");return;}JSONObject d=new JSONObject(raw);ArrayList<String> fresh=new ArrayList<>();Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null){String n=o.optString("marketDisplayName","").trim();if(n.isEmpty())n=o.optString("symbol","").trim();if(n.isEmpty())n=key;if(!fresh.contains(n))fresh.add(n);}}Collections.sort(fresh,String.CASE_INSENSITIVE_ORDER);if(!fresh.equals(allNames)){allNames.clear();allNames.addAll(fresh);filterMarkets();}updatePrice();long u=getSharedPreferences(PREF,0).getLong("markets_updated",0);status.setText("●  "+allNames.size()+" markets · updated "+Math.max(0,(System.currentTimeMillis()-u)/1000)+"s ago");}catch(Exception e){status.setText("Market data error: "+e.getMessage());}}
void updatePrice(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty())return;JSONObject item=find(new JSONObject(raw),selected());if(item==null){livePrice.setText("Current price: —");return;}Object p=item.has("markPrice")&&!item.isNull("markPrice")?item.opt("markPrice"):item.opt("oraclePrice");livePrice.setText("Current price: "+(p==null?"—":"$ "+p));}catch(Exception ignored){}}
void addLevel(EditText input){String sym=selected();double p;try{p=Double.parseDouble(input.getText().toString().trim());}catch(Exception e){p=0;}if(sym.isEmpty()||p<=0){new AlertDialog.Builder(this).setMessage("Select a market and enter a valid target price.").setPositiveButton("OK",null).show();return;}try{JSONArray a=levels();JSONObject o=new JSONObject();o.put("symbol",sym);o.put("price",p);o.put("mode",modeSpinner.getSelectedItemPosition());o.put("created",System.currentTimeMillis());o.put("enabled",true);a.put(o);save(a);input.setText("");renderLevels();}catch(Exception ignored){}}
void editLevel(int index){try{JSONArray a=levels();JSONObject old=a.getJSONObject(index);LinearLayout box=column();box.setPadding(dp(18),dp(8),dp(18),0);EditText sym=edit("Market symbol",1);sym.setText(old.optString("symbol"));box.addView(sym);EditText price=edit("Target price",8194);price.setText(old.optString("price"));box.addView(price);Spinner mode=new Spinner(this);mode.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"At price · TradingView style","Touch / cross","Near · 0.1%"}));mode.setSelection(old.optInt("mode",0));box.addView(mode);new AlertDialog.Builder(this).setTitle("Edit alert").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Save",(d,w)->{try{String s=sym.getText().toString().trim();double p=Double.parseDouble(price.getText().toString().trim());if(s.isEmpty()||p<=0)throw new Exception();old.put("symbol",s);old.put("price",p);old.put("mode",mode.getSelectedItemPosition());old.put("created",System.currentTimeMillis());a.put(index,old);save(a);renderLevels();}catch(Exception e){new AlertDialog.Builder(this).setMessage("Enter a valid market and target price.").setPositiveButton("OK",null).show();}}).show();}catch(Exception ignored){}}
void toggleLevel(int index,boolean enabled){try{JSONArray a=levels();JSONObject o=a.getJSONObject(index);o.put("enabled",enabled);a.put(index,o);save(a);renderLevels();}catch(Exception ignored){}}
void renderLevels(){if(list==null)return;list.removeAllViews();JSONArray a=levels();if(a.length()==0){TextView e=text("No alerts yet. Add your first price level above.",14,muted);list.addView(e);return;}for(int i=0;i<a.length();i++)try{final int idx=i;JSONObject o=a.getJSONObject(i);LinearLayout c=column();c.setPadding(dp(14),dp(12),dp(14),dp(12));c.setBackground(shape(card,14,Color.rgb(38,54,78)));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(9);list.addView(c,cp);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);c.addView(top);TextView symbol=text(o.optString("symbol"),16,Color.WHITE);symbol.setTypeface(null,Typeface.BOLD);top.addView(symbol,new LinearLayout.LayoutParams(0,-2,1));Switch sw=new Switch(this);sw.setChecked(o.optBoolean("enabled",true));top.addView(sw);sw.setOnCheckedChangeListener((v,on)->toggleLevel(idx,on));TextView p=text(String.format(Locale.US,"%.8f",o.optDouble("price")),22,accent);p.setPadding(0,dp(6),0,dp(2));c.addView(p);TextView mode=text(new String[]{"AT PRICE","TOUCH / CROSS","NEAR 0.1%"}[Math.max(0,Math.min(2,o.optInt("mode")))]+"  ·  "+(o.optBoolean("enabled",true)?"ACTIVE":"PAUSED"),10,muted);c.addView(mode);LinearLayout actions=new LinearLayout(this);Button edit=button("Edit");Button del=button("Delete");actions.addView(edit,new LinearLayout.LayoutParams(0,dp(42),1));actions.addView(del,new LinearLayout.LayoutParams(0,dp(42),1));c.addView(actions);edit.setOnClickListener(v->editLevel(idx));del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Delete this alert?").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->{JSONArray prev=levels(),next=new JSONArray();for(int j=0;j<prev.length();j++)if(j!=idx)next.put(prev.opt(j));save(next);renderLevels();}).show());}catch(Exception ignored){}}
void pickSound(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("audio/*");startActivityForResult(i,PICK_SOUND);}catch(Exception e){new AlertDialog.Builder(this).setMessage("Could not open sound picker.").setPositiveButton("OK",null).show();}}
protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_SOUND&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}getSharedPreferences(PREF,0).edit().putString("sound_uri",u.toString()).apply();updateSoundName();}}
void updateSoundName(){String u=getSharedPreferences(PREF,0).getString("sound_uri","");soundName.setText(u.isEmpty()?"Default notification sound":"Custom sound selected ✓");}
void testSound(){String u=getSharedPreferences(PREF,0).getString("sound_uri","");try{if(!u.isEmpty()){android.media.Ringtone r=android.media.RingtoneManager.getRingtone(this,Uri.parse(u));if(r!=null){r.play();return;}}android.media.Ringtone r=android.media.RingtoneManager.getRingtone(this,android.media.RingtoneManager.getDefaultUri(android.media.RingtoneManager.TYPE_NOTIFICATION));if(r!=null)r.play();}catch(Exception e){Toast.makeText(this,"Cannot play selected sound",Toast.LENGTH_SHORT).show();}}
void renderHistory(){if(historyList==null)return;historyList.removeAllViews();JSONArray h;try{h=new JSONArray(getSharedPreferences(PREF,0).getString("history","[]"));}catch(Exception e){h=new JSONArray();}if(h.length()==0){historyList.addView(text("No triggered alerts yet.",13,muted));return;}for(int i=h.length()-1;i>=0;i--){JSONObject o=h.optJSONObject(i);if(o==null)continue;LinearLayout c=column();c.setPadding(dp(12),dp(9),dp(12),dp(9));c.setBackground(shape(card,12,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(6);historyList.addView(c,p);c.addView(text(o.optString("symbol")+" · "+o.optString("price"),14,Color.WHITE));c.addView(text(o.optString("time"),11,muted));}}
void sendTestNotification(){try{String ch="arcus_alert_notifications_v2";NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,ch):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Arcus Alert test").setContentText("Notifications are working").setAutoCancel(true).setDefaults(Notification.DEFAULT_ALL);nm.notify(90901,b.build());}catch(Exception ignored){}}
protected void onDestroy(){handler.removeCallbacks(refresh);super.onDestroy();}
}